import {configSection,today,round} from '../core/business.js?v=20261031-v2a';
// Functions receive shared services and state through an explicit application context.
export function install(ctx){
function quoteTable(list){return list.length?`<div class="table-wrap"><table><thead><tr><th>Orçamento</th><th>Cliente</th><th>Emissão</th><th>Total</th><th>Etapa</th><th></th></tr></thead><tbody>${list.map(q=>`<tr><td><strong>#${String(q.number).padStart(4,'0')}</strong></td><td>${ctx.esc(q.client_snapshot.name)}</td><td>${ctx.date(q.created_at)}</td><td class="nowrap">${ctx.money(q.total)}</td><td>${ctx.stageBadge?ctx.stageBadge(q):ctx.esc(q.stage||"Rascunho")}</td><td><button class="secondary small" data-view="${q.id}">Abrir ${ctx.icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:ctx.empty('Seu próximo pedido começa aqui.','Crie um orçamento para acompanhar os valores e compartilhar com seu cliente.')}

function calc(cost,method,pct){if(!Number.isFinite(pct)||pct<0||(method==='margin'&&pct>=100))return NaN;return Math.round((method==='markup'?cost*(1+pct/100):cost/(1-pct/100))*100)/100}

function quoteForm(){if(!ctx.clients.length||!ctx.products.length){ctx.shell(`${ctx.head('Novo orçamento','Vamos preparar a base da sua proposta.')}<section class="panel">${ctx.empty('Falta só o primeiro passo.','Cadastre pelo menos um cliente e um produto para criar seu orçamento.')}<div class="form-actions panelbody"><button class="secondary" data-action="client-new">Cadastrar cliente</button><button class="primary" data-action="product-new">Cadastrar produto</button></div></section>`);return}
 if(!ctx.draft.length)ctx.draft=[{product_id:ctx.products[0].id,quantity:1,details:''}];const valid=new Date(Date.now()+Number(configSection(ctx.settings,'budget').validity_days)*86400000).toISOString().slice(0,10);
 ctx.shell(`${ctx.head('Novo orçamento','Escolha o cliente, personalize os itens e confira sua proposta.')}<form id="quote-form"><div class="quote-layout"><div><section class="panel"><div class="panelhead"><h2>01 · Dados da proposta</h2></div><div class="panelbody grid2"><label class="field">Cliente<select id="client" name="client" required>${ctx.clients.map(c=>`<option value="${c.id}">${ctx.esc(c.name)} · ${c.kind}</option>`).join('')}</select></label>${ctx.field('Válido até','valid','date',valid,'required')}${ctx.field('Entrega prevista','delivery_date','date','','')}${ctx.field('Entrada acordada (%)','entry_percentage','number',configSection(ctx.settings,'budget').deposit_percentage,'required min="0" max="100" step="0.01"')}<label class="field">Personalização<select name="technique">${configSection(ctx.settings,'production').techniques.map(x=>`<option>${ctx.esc(x)}</option>`).join('')}</select></label></div></section><section class="panel"><div class="panelhead"><h2>02 · Itens do orçamento</h2><span class="badge">Preços calculados pelo custo</span></div><div class="panelbody"><div id="items"></div><button type="button" class="secondary small" id="add-item">${ctx.icon('plus')} Adicionar produto</button></div></section><section class="panel"><div class="panelhead"><h2>03 · Observações e personalização</h2></div><div class="panelbody"><label class="field">Condições de pagamento, prazo de produção e observações<textarea name="notes" maxlength="10000" placeholder="Descreva as condições combinadas com o cliente…"></textarea></label><p class="muted" style="font-size:12px">Inclua tamanhos, nomes, números e descrição da arte no campo de personalização de cada item.</p></div></section></div><aside class="panel quote-summary"><div class="panelhead"><h2>Resumo da proposta</h2></div><div class="panelbody"><label class="field">Método de precificação<select id="method"><option value="markup">Acréscimo sobre o custo</option><option value="margin">Margem sobre a venda</option></select></label>${ctx.field('Percentual deste orçamento (%)','percentage','number','30','id="percentage" required min="0" max="9999" step="0.01"')}<p id="method-note" class="note"></p><div class="divider"></div><div class="muted" style="font-size:12px">Valor total do orçamento</div><div class="total" id="total"></div><p id="quote-error" role="alert"></p><button type="submit" class="primary wide">Salvar orçamento ${ctx.icon('arrow')}</button><p class="muted" style="font-size:11px">Após salvar, você poderá imprimir ou salvar em PDF.</p></div></aside></div></form>`);
 const update=()=>{const method=ctx.$('#method').value,pct=Number(ctx.$('#percentage').value);ctx.$('#percentage').max=method==='margin'?'99.99':'9999';ctx.$('#method-note').textContent=method==='markup'?'Acréscimo: custo × (1 + percentual). Ex.: custo R$ 100 + 30% = R$ 130.':'Margem: custo ÷ (1 − percentual). Ex.: custo R$ 100 com 30% de margem = R$ 142,86.';let total=0;ctx.draft.forEach((it,i)=>{const p=ctx.products.find(p=>p.id===it.product_id),price=ctx.calc(Number(p.cost),method,pct);total+=price*Number(it.quantity);const node=ctx.$('#price-'+i);if(node)node.textContent=Number.isFinite(price)?ctx.money(price):'Inválido'});ctx.$('#total').textContent=Number.isFinite(total)?ctx.money(total):'Percentual inválido'};
 function rows(){ctx.$('#items').innerHTML=ctx.draft.map((it,i)=>`<div class="quote-row"><label class="field">Produto<select data-item="${i}" data-key="product_id">${ctx.products.map(p=>`<option value="${p.id}" ${p.id===it.product_id?'selected':''}>${ctx.esc(p.name)}</option>`).join('')}</select></label><label class="field">Qtd.<input aria-label="Quantidade item ${i+1}" data-item="${i}" data-key="quantity" type="number" min="1" max="100000" step="1" required value="${it.quantity}"></label><div class="field">Unitário<strong id="price-${i}" style="padding:13px 0;font-size:13px"></strong></div><button type="button" class="ghost small" data-remove="${i}" aria-label="Remover item ${i+1}">${ctx.icon('x')}</button><textarea aria-label="Personalização item ${i+1}" data-item="${i}" data-key="details" maxlength="5000" placeholder="Personalização: arte, tamanhos, nomes e números…">${ctx.esc(it.details)}</textarea></div>`).join('');document.querySelectorAll('[data-item]').forEach(el=>el.oninput=()=>{ctx.draft[el.dataset.item][el.dataset.key]=el.value;update()});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(ctx.draft.length===1)return ctx.toast('Mantenha pelo menos um item.');ctx.draft.splice(Number(b.dataset.remove),1);rows()});update()}
 ctx.$('#method').value=ctx.settings.method||'markup';ctx.$('#percentage').value=ctx.settings.percentage??30;ctx.$('[name=notes]').value=ctx.settings.conditions||'';rows();ctx.$('#method').onchange=update;ctx.$('#percentage').oninput=update;ctx.$('#add-item').onclick=()=>{if(ctx.draft.length>=100)return ctx.toast('Limite de 100 itens por orçamento.');ctx.draft.push({product_id:ctx.products[0].id,quantity:1,details:''});rows()};
 ctx.$('#quote-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const f=new FormData(e.target);const id=await ctx.api('/rest/v1/rpc/create_quote_v2',{method:'POST',body:{p_client:f.get('client'),p_method:ctx.$('#method').value,p_percentage:Number(ctx.$('#percentage').value),p_valid_until:f.get('valid'),p_notes:f.get('notes'),p_meta:{delivery_date:f.get('delivery_date'),entry_percentage:Number(f.get('entry_percentage')),technique:f.get('technique')},p_items:ctx.draft.map(it=>({...it,quantity:Number(it.quantity)}))}});ctx.draft=[];await ctx.load();await ctx.openQuote(id);ctx.toast('Orçamento salvo com sucesso.')}catch(err){ctx.$('#quote-error').className='error';ctx.$('#quote-error').textContent=err.message;b.disabled=false}};
}

async function openQuote(id){try{const q=ctx.quotes.find(q=>q.id===id);if(!q)throw Error('Orçamento não encontrado.');const items=await ctx.api('/rest/v1/quote_items?quote_id=eq.'+id+'&select=*&order=id');ctx.viewQuote={...q,items};ctx.render('view')}catch(e){ctx.toast(e.message)}}

function printView(){const q=ctx.viewQuote,c=q.client_snapshot,company=q.company_snapshot||{},budget=company.budget||{},entry=round(Number(q.total)*Number(q.entry_percentage??50)/100);ctx.shell(`${ctx.head('Orçamento #'+String(q.number).padStart(4,'0'),'Proposta salva. Os preços deste documento preservam o histórico.')}<div class="form-actions" style="border:0;padding:0;margin-bottom:25px"><button class="secondary" data-action="quotes">Voltar para orçamentos</button>${ctx.can('workflow')?'<button class="secondary" id="quote-workflow">Ver pedido / produção</button>':''}${ctx.can('finance','create')?'<button class="secondary" id="quote-receivables">Gerar entrada e saldo</button>':''}<button class="primary" id="print">${ctx.icon('print')} Imprimir / Salvar PDF</button></div><article class="quote-print"><header><div><div class="brand ${company.logo?'custom-brand':'document-brand'}"><img src="${ctx.esc(company.logo||'logo-document.png')}" alt="${ctx.esc(company.company||'Avelon Têxtil')}"></div><p>${ctx.esc(company.company||'AVELON TÊXTIL · Confecções')}<br>${ctx.esc(company.contact||'Onde sua imaginação ganha forma.')}</p></div><div><h1>ORÇAMENTO</h1><p><strong>Nº ${String(q.number).padStart(4,'0')}</strong><br>Emissão: ${ctx.date(q.created_at)}<br>Validade: ${ctx.date(q.valid_until)}</p></div></header><div class="eyebrow">Preparado para</div><h2 style="font:700 20px Manrope">${ctx.esc(c.name)}</h2><p>${ctx.esc(c.kind)}${c.document?' · '+ctx.esc(c.document):''}<br>${ctx.esc(c.phone)}${c.email?' · '+ctx.esc(c.email):''}<br>${ctx.esc(c.address)}</p><div class="table-wrap"><table><thead><tr><th>Produto e personalização</th><th>Qtd.</th><th>Unitário</th><th>Subtotal</th></tr></thead><tbody>${q.items.map(it=>`<tr><td><strong>${ctx.esc(it.description)}</strong><div class="details">${ctx.esc(it.details)}</div></td><td>${it.quantity}</td><td class="nowrap">${ctx.money(it.unit_price)}</td><td class="nowrap">${ctx.money(it.quantity*it.unit_price)}</td></tr>`).join('')}</tbody></table></div><div class="print-total">Valor total <strong>${ctx.money(q.total)}</strong></div>${q.entry_percentage!==undefined?`<p><strong>Entrada acordada (${q.entry_percentage}%):</strong> ${ctx.money(entry)} · <strong>Saldo:</strong> ${ctx.money(round(q.total-entry))}<br>${budget.payment_methods?'Pagamento: '+ctx.esc(budget.payment_methods):''}${budget.production_days?'<br>Prazo estimado de produção: '+budget.production_days+' dias após confirmação, entrada e aprovação da arte.':''}${q.delivery_date?'<br>Entrega prevista: '+ctx.date(q.delivery_date):''}</p>`:''}${q.notes?`<div class="divider"></div><div class="eyebrow">Condições e observações</div><p>${ctx.esc(q.notes)}</p>`:''}${budget.show_notes!==false&&budget.important_notes?`<section class="budget-notes"><h3>Orientações importantes</h3><p>${ctx.esc(budget.important_notes)}</p></section>`:''}${budget.show_signature!==false&&company.signature?`<div class="document-signature"><img class="${company.signature_invert?'invert-signature':''}" src="${ctx.esc(company.signature)}" alt="Assinatura de ${ctx.esc(company.signature_name||'responsável')}"><p>${ctx.esc(company.signature_name)}<br>${ctx.esc(company.city||budget.city||'')}, ${ctx.date(q.created_at)}</p></div>`:''}<div class="divider"></div><p class="muted">Obrigado por escolher a Avelon Têxtil.<br>Esta proposta é válida até ${ctx.date(q.valid_until)}. Produção sujeita à confirmação das condições acordadas.</p></article>`);ctx.$('#quote-workflow')?.addEventListener('click',()=>ctx.orderDialog(q.id));ctx.$('#quote-receivables')?.addEventListener('click',()=>ctx.receivableDialog(q.id));if(ctx.$('#print'))ctx.$('#print').onclick=async()=>{try{await ctx.api('/rest/v1/rpc/quote_print_data',{method:'POST',body:{p_quote:q.id}});window.print()}catch(e){ctx.toast(e.message)}}}
function quotesPage(){ctx.shell(`${ctx.head('Orçamentos','Propostas, pedidos e histórico dos documentos.','quote','Novo orçamento')}<div class="toolbar"><input type="search" id="quote-search" placeholder="Buscar cliente ou número…" aria-label="Buscar orçamento"></div><section class="panel" id="quote-list">${quoteTable(ctx.quotes)}</section>`);ctx.$('#quote-search').oninput=e=>{const s=e.target.value.toLowerCase();ctx.$('#quote-list').innerHTML=quoteTable(ctx.quotes.filter(q=>(q.number+' '+q.client_snapshot.name).toLowerCase().includes(s)));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>openQuote(b.dataset.view))}}
Object.assign(ctx,{quoteTable,calc,quoteForm,openQuote,printView,quotesPage});
}
